/* eslint-disable */
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
export type AccountStatus =
  | 'ACTIVE'
  | 'AGE_BLOCKED'
  | 'BLOCKED'
  | 'SUSPENDED';

/** What an achievement marks */
export type AchievementKind =
  /** Exams that reached their Readiness target before the day */
  | 'EXAM_READY'
  /** Topics with at least 30 quiz answers, nine in ten right */
  | 'QUIZ_MASTER'
  /** Weeks whose planned days were met */
  | 'RHYTHM_WEEKS'
  /** Points from public notes on one subject */
  | 'SUBJECT_CONTRIBUTOR'
  /** Topics recalled well and answered right (mastery ≥ 0.8) */
  | 'TOPICS_MASTERED';

export type ActivityKind =
  | 'CLASS_ANNOUNCEMENT'
  | 'DOUBT'
  | 'GROUP_POST'
  | 'IDEA'
  | 'REPOSITORY'
  | 'SHARED_NOTE';

