/** What a listed model is. A picker offers it only when `supports` includes that picker's use. */
export type AiModelKind =
  | 'AUDIO'
  | 'CHAT'
  | 'EMBEDDING'
  | 'IMAGE'
  | 'MODERATION'
  | 'OTHER'
  | 'REALTIME'
  | 'TTS';

/**
 * A select on /admin/ai. IMAGE, TTS, AUDIO, REALTIME and MODERATION stay empty.
 * TRANSCRIBE offers models that can hear. Whisper and *-transcribe go to POST /audio/transcriptions.
 * gpt-audio, Gemini and Gemma take the recording on the chat call.
 */
export type AiModelUse =
  /** Reserved. Whisper is offered on TRANSCRIBE, so this picker stays empty. */
  | 'AUDIO'
  /** The connection's chat model, and every task route except embeddings and transcription */
  | 'CHAT'
  /** The connection's embedding model, and the EMBED route. Embeddings are 768 numbers. */
  | 'EMBEDDING'
  /** Image generation. This app does not call it, so the picker is empty. */
  | 'IMAGE'
  /** Moderation models. This app does not call them, so the picker is empty. */
  | 'MODERATION'
  /** Realtime. This app does not call it, so the picker is empty. */
  | 'REALTIME'
  /** The TRANSCRIBE route: a model that can hear a recording */
  | 'TRANSCRIBE'
  /** Speech. This app does not call it, so the picker is empty. */
  | 'TTS';

/** Who answers AI calls */
export type AiProviderKind =
  | 'ANTHROPIC'
  | 'GEMINI'
  | 'OLLAMA'
  | 'OPENAI'
  /** Any server that speaks OpenAI's API: a LiteLLM proxy, OpenRouter, vLLM… */
  | 'OPENAI_COMPATIBLE';

export type AiTask =
  /** Mends what PDF conversion broke in the text, heading and quote cards of a note the person may edit, as changes to apply (ADR-0063) */
  | 'CLEAN_UP'
  /** Needs the right to copy the note (ADR-0025) */
  | 'CREATE_NOTES'
  /** On the note's code cards */
  | 'EXPLAIN_CODE'
  | 'EXPLAIN_SIMPLY'
  | 'FIND_MISTAKES'
  | 'FLASHCARDS'
  | 'KEY_CONCEPTS'
  /** Needs the right to copy the note (ADR-0025) */
  | 'OUTLINE_TO_NOTE'
  | 'PRACTICE_QUESTIONS'
  /** The person's own note's rough words and photos, as a structured note (ADR-0062) */
  | 'QUICK_NOTE'
  | 'QUIZ'
  | 'REVISION_SHEET'
  | 'SUMMARIZE'
  /** One audio or video card (cardIds), as a text card to keep (ADR-0062) */
  | 'TRANSCRIBE'
  | 'TRANSLATE';

export type AiTaskRouteInput = {
  task: string;
};

/** Why AI is not answering */
export type AiUnavailableReason =
  /** This month's AI budget is used up; it resumes next month */
  | 'BUDGET'
  /** Not switched on in this environment */
  | 'NOT_CONFIGURED'
  /** The model failed several times in a row; it is tried again shortly */
  | 'PROVIDER_DOWN';

